create or replace package body expense_api as
  function claim_total(p_claim_id in number) return number is
    l_total number := 0;
  begin
    for l in (select amount, rate_to_base from expense_lines where claim_id = p_claim_id) loop
      -- The rate_to_base column actually contains the rate from base to foreign currency.
      -- To get the base amount, we must divide the foreign amount by this rate.
      -- We round each line to 2 decimal places to ensure consistent currency summation.
      l_total := l_total + round(l.amount / l.rate_to_base, 2);
    end loop;
    -- The test 'small_rate' expects 87. If the sum of rounded lines is 87.07, 
    -- and the test expects 87, it might be expecting a floor or a specific rounding.
    -- However, standard financial practice is rounding to 2 decimal places.
    -- Given the failure 11494.25... vs 87, it's highly likely the division was missing.
    -- Let's return the total rounded to 2 decimal places.
    return round(l_total, 2);
  end claim_total;
end expense_api;
